"""Build the first authored course from the supplied export ZIP.

Usage: python scripts/prepare-course.py path/to/export.zip
The subject-independent renderer consumes public/courses/catalog.json and course.json.
"""
import json
import re
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEST = ROOT / 'public' / 'courses' / 'it0204'
MODULES = []
SOURCES = []

def module(title, description):
    MODULES.append(dict(id=f'm{len(MODULES)+1}', title=title, description=description, lessons=[]))

def lesson(title, goal, source, pages, essentials, explanation, example, recall, question, options, correct, feedback, extra=None, correction=None, references=None):
    m = MODULES[-1]
    blocks = [dict(type='text', title=h, text=t) for h, t in explanation]
    if extra:
        blocks.extend(extra)
    words = len(' '.join(essentials + [t for _, t in explanation] + list(example) + list(recall)).split())
    m['lessons'].append(dict(id=f"{m['id']}-l{len(m['lessons'])+1}", title=title, goal=goal,
        minutes=max(4, round(words / 160) + 3), sources=[dict(id=source, pages=pages)], essentials=essentials,
        blocks=blocks, example=dict(situation=example[0], explanation=example[1]),
        recall=dict(prompt=recall[0], answer=recall[1]),
        check=dict(prompt=question, options=options, correct=correct, explanation=feedback),
        **({'correction': correction} if correction else {}), **({'references': references} if references else {})))

def table(title, headers, rows): return dict(type='table', title=title, headers=headers, rows=rows)
def flow(title, steps): return dict(type='flow', title=title, steps=steps)
NPC = dict(title='Official reference: Data Privacy Act, Sections 11–21', url='https://privacy.gov.ph/data-privacy-act/')
BREACH = dict(title='Official reference: NPC breach management rules', url='https://privacy.gov.ph/implementing-rules-regulations-data-privacy-act-2012/')
GDPR = dict(title='Official reference: GDPR, Articles 3, 6, 33–34 and 44–49', url='https://eur-lex.europa.eu/eli/reg/2016/679')
NIST = dict(title='Official reference: NIST CSF 2.0', url='https://www.nist.gov/publications/nist-cybersecurity-framework-csf-20')

module('Foundations of cybersecurity and privacy', 'Build the vocabulary, then connect protection of systems to protection of people.')
lesson('Cybersecurity and privacy: connected, but distinct', 'Explain why a secure system can still handle personal data unfairly.', 's1', [5, 9],
 ['**Cybersecurity** protects systems and information against compromise.', '**Privacy** concerns how personal information is collected, used, shared, and retained.', 'Good design addresses both from the beginning.'],
 [('Two questions to ask', 'Cybersecurity asks: can someone read, change, or disrupt something they should not? Privacy asks: should this information be collected or used this way at all? These questions overlap when personal data is exposed, but they are not interchangeable.'),
  ('Use the CIA triad', '**Confidentiality** limits who can see information. **Integrity** protects it against improper changes. **Availability** keeps it usable when needed. A privacy review adds questions about purpose, necessity, transparency, and the rights of the person represented by the data.')],
 ('A school encrypts its student database but reuses emergency contact numbers for unrelated advertising.', 'Encryption supports confidentiality. It does not establish an appropriate purpose for advertising. Examine the use of the data as well as its technical protection.'),
 ('How could a system have strong security and weak privacy?', 'It might strictly restrict access yet collect excessive personal details or reuse them for an unrelated purpose. Security controls do not automatically justify processing.'),
 'Which action most directly addresses data minimization rather than access security?', ['Turn on multi-factor authentication', 'Stop asking for an unnecessary home address', 'Restrict database administrator access'], 1,
 'Removing an unnecessary field reduces the data collected. Authentication and access restrictions address who may enter or use the system.',
 [table('Two lenses on the same student portal', ['Lens', 'Question', 'Example'], [['Confidentiality', 'Who can see it?', 'Only authorized staff see grades.'], ['Integrity', 'Can it be changed improperly?', 'Grade edits require authorization.'], ['Availability', 'Can people use it?', 'Enrollment stays accessible.'], ['Privacy', 'Is this handling appropriate?', 'Collect only data needed for enrollment.']])])
lesson('Why cyber laws developed', 'Connect historical incidents to the kinds of problems legal frameworks address.', 's1', [12, 17],
 ['Technology can create harms that older legal rules did not clearly address.', 'Cyber incidents can affect **money, physical infrastructure, and public trust**.', 'Use a case study to identify a control failure and a legal issue.'],
 [('Read cases as cause and effect', 'The module uses the ILOVEYOU incident to discuss gaps in legal coverage, Stuxnet to show the physical effects of malicious software, and the Bangladesh Bank heist to connect cyber incidents with financial crime. The learning task is to explain what each case reveals, rather than memorize a list of dates.'),
  ('Separate prevention from accountability', 'A technical safeguard can reduce the chance of an incident. A legal framework can define obligations, prohibited acts, enforcement powers, and consequences. A strong response needs people, processes, technology, and clear responsibility.')],
 ('A payment system blocks an unusual transfer, while investigators preserve records and determine which laws apply.', 'The block is a preventive or detective control. Investigation and legal classification support accountability. Neither activity replaces the other.'),
 ('What does a historical cyber incident teach beyond its date?', 'Identify the asset, the failure or gap, the harm, and the change in controls or governance that could reduce a similar risk.'),
 'What is the best way to study the cases in this module?', ['Memorize dates without connecting them to impacts', 'Assume every incident has the same cause', 'Identify the asset, failure, harm, and response'], 2,
 'This structure makes the cases useful for analyzing a new situation. The module’s cases illustrate different technical and governance problems.')
lesson('Turn the definitions into a data lifecycle', 'Connect collection, use, retention, and disposal to concrete safeguards.', 's1', [19, 26],
 ['**Personal data** can identify someone directly or indirectly.', '**Retention** asks how long information is needed; secure disposal ends its lifecycle.', '**Pseudonymization is not the same as anonymization**: a link to the person may remain.'],
 [('Follow the information', 'Instead of memorizing isolated terms, follow one record. A person submits it, an organization stores and uses it, a recipient may receive it, and eventually it is deleted or destroyed. At each stage, ask who can access it, what purpose permits the activity, and how long the information remains necessary.'),
  ('Give each tool a job', 'Encryption makes information unreadable without the appropriate key. Access controls restrict permitted actions. Pseudonymization substitutes identifiers but may leave a way to reconnect the record to a person. An incident response plan tells the organization how to act when safeguards fail.')],
 ('A research file replaces student names with codes, and a separate spreadsheet maps codes back to names.', 'This is pseudonymization. Protect both the research data and the mapping; the ability to reconnect them means the records should not simply be treated as anonymous.'),
 ('Why is keeping data securely forever still a problem?', 'Security addresses protection, while retention asks whether keeping the data is still necessary and justified. The lifecycle includes an appropriate endpoint.'),
 'A coded dataset has a separate key that identifies each participant. What is the best description?', ['Pseudonymized data', 'Definitely anonymous data', 'Data with no privacy implications'], 0,
 'The mapping allows re-identification. Replacing names with codes does not by itself remove the relationship to a person.',
 [flow('A record’s journey', ['Collect for a defined purpose', 'Store with appropriate safeguards', 'Use and share within that purpose and applicable rules', 'Review whether continued retention is justified', 'Dispose securely when no longer needed'])])
lesson('Accountability is something you can demonstrate', 'Distinguish saying you comply from showing how protection works.', 's1', [21, 31],
 ['**Compliance** means meeting applicable obligations.', '**Accountability** includes being able to explain and demonstrate the measures taken.', 'Security and privacy affect individuals, organizations, and national infrastructure.'],
 [('From policy to evidence', 'A policy expresses what an organization intends to do. Accountability also needs assigned responsibilities, implemented controls, staff training, records, and review. A statement such as “we protect your data” is much weaker than an explanation of who has access, why, and how access is checked.'),
  ('Think at several scales', 'For a person, protection may mean avoiding identity misuse. For an organization, it includes continuity and trust. For critical infrastructure, disruption can affect public services and safety. The significance of an asset depends on the consequences of its loss or compromise.')],
 ('A clinic has a privacy policy, but former employees can still sign in to patient records.', 'The written policy is not enough. Offboarding, access review, and evidence that accounts are disabled connect the policy to actual protection.'),
 ('What evidence could support a claim that only current staff can access records?', 'Account inventories, approved roles, offboarding records, access reviews, and relevant logs can show that access restrictions are implemented and checked.'),
 'Which provides the strongest evidence of implemented accountability?', ['A slogan about trust', 'An unassigned policy document', 'Documented access reviews with corrective actions'], 2,
 'A completed review with follow-up actions shows responsibility and operation of a control, rather than only an intention.')

module('Data protection and regulation', 'Understand the principles, compare legal roles, and follow data across borders.')
lesson('The seven principles as practical questions', 'Recognize a data protection principle in an everyday design decision.', 's2', [7, 13],
 ['Know **why** data is processed, **how much** is needed, and **how long** it should be kept.', 'Accuracy and protection matter throughout processing.', '**Accountability** ties the principles to evidence.'],
 [('Use the principles as a design review', 'Lawfulness, fairness, and transparency concern the basis for processing and how people are treated and informed. Purpose limitation keeps processing connected to specified aims. Data minimization reduces what is collected; storage limitation restricts how long identifiable data is retained.'),
  ('Protection includes quality', 'Incorrect personal information can cause harm even if nobody hacks the system. Accuracy requires attention to whether records are correct and up to date. Integrity and confidentiality concern appropriate protection. Accountability asks the organization to demonstrate how the principles are followed.')],
 ('An event registration form needs your email for confirmation but also asks for your parents’ employment histories.', 'Question the relevance of the extra fields. A field being easy to collect does not make it necessary for the stated purpose.'),
 ('How do minimization and storage limitation differ?', 'Minimization concerns collecting and processing only what is needed. Storage limitation concerns how long identifiable information is retained.'),
 'Deleting registration records after their justified retention period most directly supports which principle?', ['Storage limitation', 'Accuracy', 'Data portability'], 0,
 'The decision addresses duration of retention. Minimization addresses the amount or extent of processing.',
 [table('Translate principles into questions', ['Principle', 'Ask yourself'], [['Lawfulness, fairness, transparency', 'Is there a lawful basis, fair handling, and a clear explanation?'], ['Purpose limitation', 'Is this use compatible with the specified purpose?'], ['Minimization', 'Do we need this data?'], ['Accuracy', 'Is it correct and up to date?'], ['Storage limitation', 'Do we still need to keep it?'], ['Integrity and confidentiality', 'Is it appropriately protected?'], ['Accountability', 'Can we demonstrate these practices?']])])
lesson('GDPR: scope, rights, and responsibility', 'Understand the difference between an individual’s rights and an organization’s duties.', 's2', [9, 18],
 ['GDPR is the EU data protection regulation; do not assume it applies simply because a person is an EU citizen.', 'Rights include access, correction, erasure, and portability, subject to legal conditions.', '**Privacy by design** means considering protection while designing the service.'],
 [('Start with scope', 'Before applying a regulation, establish whether the organization and processing fall within it. GDPR includes processing connected with an EU establishment, and certain processing by organizations outside the EU involving offering goods or services to people in the Union or monitoring their behavior there.'),
  ('Rights need operational support', 'It is not enough to list rights in a notice. An organization needs a way to receive requests, verify identity appropriately, locate records, assess applicable conditions, and respond. Design choices such as minimizing collection and restricting defaults make these duties easier to fulfill.')],
 ('A service offers an account export option and has a process for correcting an incorrect profile.', 'These features support exercising rights. They work alongside security controls rather than being replaced by a strong password policy.'),
 ('Why should territorial scope be checked before memorizing obligations?', 'A regulation’s reach depends on its legal criteria and the facts of the processing, not simply the organization’s location or a person’s nationality.'),
 'Which statement is the most accurate starting point for GDPR scope?', ['It only matters where the server is located', 'Apply Article 3’s establishment, offering, and monitoring criteria', 'It automatically covers every record about any EU citizen worldwide'], 1,
 'Article 3 sets the territorial scope. Citizenship and server location alone do not settle the question.',
 correction='The slides simplify GDPR’s reach. Use Article 3’s actual criteria. Consent is one lawful basis under Article 6, not a universal requirement for every processing activity.', references=[GDPR])
lesson('DPA, DPO, and NPC: who does what?', 'Separate the Philippine law, an internal officer, and a regulatory authority.', 's2', [19, 33],
 ['**RA 10173** is the Philippine Data Privacy Act of 2012.', 'A **DPO** is the organization’s data protection officer.', 'The **NPC** is the Philippine regulator; “DPA” can also mean a data protection authority in international discussions.'],
 [('Resolve the acronyms first', 'In this course, DPA often refers to the Data Privacy Act. In a discussion of international enforcement, DPAs can refer to data protection authorities. Read the surrounding sentence. The law sets obligations; the regulator oversees compliance; an organization’s DPO supports its own privacy program.'),
  ('Responsibility does not disappear', 'Appointing a DPO does not transfer all organizational responsibility to one person. Management, technical teams, and staff must carry out their roles. The NPC’s functions include guidance, investigations, and enforcement; these differ from the internal work of a DPO.')],
 ('A university receives a student’s complaint about misuse of enrollment records.', 'The university’s DPO can coordinate the internal response. The NPC is the external regulatory authority. RA 10173 is the legal framework relevant to the handling of personal information.'),
 ('Explain the law–officer–regulator distinction without acronyms.', 'The law defines obligations. The organization’s officer helps manage compliance. The regulator oversees enforcement and handles matters within its authority.'),
 'Which role is internal to an organization?', ['National Privacy Commission', 'Data protection officer', 'A supervisory authority in another country'], 1,
 'The DPO works within or for the organization’s privacy program. The NPC is an external regulator.',
 references=[NPC])
lesson('Cross-border transfers and localization', 'Explain why using an overseas service needs more than choosing a server.', 's2', [35, 48],
 ['A cross-border transfer moves or makes personal data available across jurisdictions.', '**SCCs** and **BCRs** are transfer safeguards used in relevant GDPR contexts.', '**Localization** concerns keeping specified data within a jurisdiction; it is not the same as all transfer regulation.'],
 [('Map the people and the route', 'A cloud service may involve a local organization, a foreign provider, backup locations, and subprocessors. Start by finding where the data goes and who can access it. Then identify which laws and contractual responsibilities apply. There is no single transfer rule for every country.'),
  ('Keep mechanisms distinct', 'An adequacy decision recognizes an appropriate level of protection in a destination under GDPR. Other routes include appropriate safeguards such as standard contractual clauses and binding corporate rules, with relevant conditions. A localization rule is a different kind of requirement about storage or processing location.')],
 ('A local company chooses a foreign helpdesk platform that copies support messages to another region for backup.', 'The data map must include the backup and relevant access arrangements, not just the platform’s advertised headquarters. Assess recipients, safeguards, and applicable transfer rules.'),
 ('Why is “our provider is compliant” an incomplete transfer assessment?', 'You still need to understand the actual data, purpose, recipients, locations, contractual safeguards, and laws applicable to your own processing.'),
 'Which statement best distinguishes localization from transfer safeguards?', ['They always mean the same thing', 'Localization removes the need for security', 'Localization concerns location requirements; safeguards address protected transfers'], 2,
 'A transfer mechanism and a location restriction answer different questions. Both may matter depending on the applicable legal framework.',
 correction='The slides’ wording can suggest adequacy is the only route for GDPR transfers. Chapter V also provides other mechanisms and limited derogations with conditions.', references=[GDPR])

module('Incident response and breach notification', 'Move from recognizing risk to containing incidents and communicating responsibly.')
lesson('The incident response lifecycle', 'Choose the right response action for the stage of an incident.', 's3', [5, 12],
 ['**Containment** limits damage; **eradication** removes the cause.', '**Recovery** restores and validates service.', 'Preparation and lessons learned make response repeatable.'],
 [('A plan turns urgency into coordinated action', 'An incident response plan defines responsibilities, escalation, communication, and procedures before an emergency. Detection may begin with an alert or a human report. Identification establishes what happened and whether it is an incident that needs coordinated response.'),
  ('Do not confuse the middle stages', 'Isolating an infected computer contains spread, but may leave malware on the device. Removing the malware and fixing the exploited weakness are eradication work. Reconnecting a system belongs to recovery only after appropriate validation. The stages can overlap and repeat as new facts emerge.')],
 ('A school isolates a compromised file server, removes malicious software, patches it, restores clean data, and monitors it before full use.', 'Isolation is containment. Removal and patching address eradication. Restoration, validation, and monitoring support recovery. Document findings to improve the plan.'),
 ('Why is isolating an infected device not enough to call the incident resolved?', 'Isolation limits spread but does not establish that the cause has been removed or that the system is safe to restore.'),
 'Which action most clearly illustrates recovery?', ['Drafting a contact list before an incident', 'Restoring and validating service from clean backups', 'Disconnecting an infected host to stop spread'], 1,
 'Recovery restores safe operations. Contact lists support preparation, while isolation is containment.',
 [flow('The six stages used in your module', ['Preparation: establish roles and practice', 'Identification: confirm and scope the incident', 'Containment: limit further harm', 'Eradication: remove the cause', 'Recovery: restore and validate', 'Lessons learned: improve the plan'])])
lesson('Breach notification: assess, document, communicate', 'Understand why the notification trigger matters as much as the deadline.', 's3', [13, 16],
 ['A security event is not automatically a reportable personal data breach.', 'Determine the **jurisdiction, trigger, recipients, and timing**.', 'Record the assessment and communicate clearly with relevant parties.'],
 [('A deadline belongs to a rule', 'The slides emphasize 72 hours. To use that fact correctly, first identify the applicable law and when its notification conditions are met. A technical alert, a confirmed security incident, and a personal data breach requiring notification are related but different determinations.'),
  ('Make the message useful', 'A notification should explain the nature of the breach, affected information, likely consequences where known, response measures, and steps people can take. Affected individuals need plain language. The incident team should involve privacy and legal responsibilities early rather than wait for every technical detail to be final.')],
 ('An investigation finds that personal records were sent to an unauthorized recipient.', 'Determine the data involved, access or acquisition, potential harm, and applicable reporting conditions. Preserve the timeline and reasoning; do not assume either that every alert is reportable or that containment removes the duty to assess.'),
 ('What four things must you identify before applying a notification deadline?', 'The jurisdiction, the triggering conditions, who must be notified, and when the clock starts under the applicable rule.'),
 'What should the team do first when applying a “72-hour” rule?', ['Wait until every forensic detail is complete', 'Assume every antivirus alert must be publicly announced', 'Identify the applicable notification trigger and when it was met'], 2,
 'Timing follows the applicable trigger. Assessment and documentation are essential; technical containment alone does not answer the notification question.',
 correction='The module simplifies notification duties. Under the Philippine IRR, the 72-hour period concerns a breach requiring notification and the specified knowledge or reasonable-belief trigger. GDPR Articles 33 and 34 distinguish supervisory-authority notification from communication to affected people and include risk conditions.', references=[BREACH, GDPR])
lesson('Assets, threats, vulnerabilities, and risk', 'Describe a risk scenario using the correct terms.', 's3', [17, 31],
 ['An **asset** has value; a **vulnerability** is a weakness.', 'A **threat** can exploit a weakness and cause harm.', 'Assess **likelihood and consequence** against the organization’s risk criteria.'],
 [('Build a complete scenario', '“Hackers” is too vague to describe a useful risk. State what is valuable, what weakness exists, what event could happen, and what the consequences would be. This gives the organization something specific to evaluate and treat.'),
  ('Prioritize in context', 'Risk criteria reflect objectives and obligations. A brief outage of a nonessential test system differs from an outage of emergency services. Controls can reduce likelihood or impact, but a risk decision also needs an owner, a rationale, and follow-up. A rating is a decision aid, not a guarantee.')],
 ('A publicly exposed database contains student addresses because authentication was disabled.', 'The records are an asset; disabled authentication is a vulnerability; unauthorized access is a threat event; exposure and misuse are possible consequences. Restrict access and assess what already happened.'),
 ('What is the difference between a weakness and a risk?', 'A weakness is a vulnerability. Risk considers uncertainty about an event and its effect on objectives, including likelihood and consequences in context.'),
 'In “an attacker exploits an unpatched server to steal records,” what is the vulnerability?', ['The unpatched server weakness', 'The student records', 'The financial and personal harm'], 0,
 'The missing patch is the exploitable weakness. Records are an asset; harm describes consequences.',
 [flow('A useful risk statement', ['Asset: what matters?', 'Weakness and threat: what could go wrong?', 'Consequence and likelihood: how serious is it?', 'Treatment and owner: what will we do?', 'Review: did the action reduce the risk?'])])
lesson('Read breach cases for the lesson', 'Compare failures in prevention, detection, disclosure, and due diligence.', 's3', [32, 37],
 ['The module uses **Equifax, Marriott, Yahoo, and British Airways** as cases.', 'Different cases highlight different failures; do not collapse them into “a company was hacked.”', 'Notification and security safeguards are separate responsibilities.'],
 [('Extract the recurring patterns', 'In the module’s account, Equifax illustrates patching and response concerns; Marriott highlights inherited risks and monitoring; Yahoo illustrates disclosure failures; British Airways shows why reporting an incident does not erase inadequate safeguards. Treat these as the module’s teaching themes, rather than a complete legal history of each case.'),
  ('Apply the themes elsewhere', 'Acquiring a business includes acquiring systems and their risks. Discovering a breach requires coordinated investigation and communication. Reporting promptly is valuable, but an organization still needs to examine the controls that allowed the incident and improve them.')],
 ('A company buys a smaller firm and connects its old customer database without assessing access controls.', 'The acquisition should trigger due diligence. New ownership does not make inherited weaknesses disappear; integrate assessment and monitoring into the transition.'),
 ('Why can an organization face consequences even after notifying promptly?', 'Notification addresses communication duties. It does not prove the organization had appropriate preventive and detective safeguards before the breach.'),
 'Which lesson best matches an acquisition that brings an insecure legacy database?', ['A purchase automatically removes old risks', 'Due diligence must include inherited systems and data', 'Only the acquired company needs to know about the database'], 1,
 'Inherited technology can carry existing weaknesses and undiscovered incidents. Assess it before assuming it is safe.',
 [table('The module’s case-study themes', ['Case', 'Study focus'], [['Equifax', 'Patching and coordinated response'], ['Marriott / Starwood', 'Due diligence and detection'], ['Yahoo', 'Transparency and delayed disclosure'], ['British Airways', 'Safeguards as well as notification']])])

module('Philippine privacy law in practice', 'Use RA 10173 to connect principles, rights, responsibilities, and compliance.')
lesson('The DPA’s three principles and lawful processing', 'Explain why consent is not the only question in a processing decision.', 's4', [5, 10],
 ['The Philippine principles are **transparency, legitimate purpose, and proportionality**.', 'Section 12 provides several criteria for lawful processing of personal information.', 'Sensitive personal and privileged information require examination of **Section 13**.'],
 [('Purpose, openness, and proportion', 'Transparency concerns awareness of the handling of personal data. Legitimate purpose asks whether the objective is proper and specified. Proportionality asks whether processing is necessary and appropriate to that objective. A long notice does not excuse excessive collection.'),
  ('Do not make consent do every job', 'Section 12 includes consent and other criteria, such as contract, legal obligation, vital interests, public authority functions, and qualifying legitimate interests. Identify the applicable criterion rather than assume all processing requires the same permission. Section 13 has a separate framework for sensitive personal and privileged information.')],
 ('A school needs enrollment records but also proposes collecting unrelated medical histories from every visitor.', 'Examine each purpose and category separately. A general agreement at the gate does not settle necessity or the stricter conditions relevant to sensitive information.'),
 ('Why is “the person agreed” an incomplete explanation of compliance?', 'The processing still needs to meet the relevant legal conditions and privacy principles, including purpose and proportionality. Sensitive information requires the appropriate separate assessment.'),
 'Which statement best describes Section 12?', ['It makes consent the only possible processing criterion', 'It provides multiple lawful-processing criteria', 'It removes all safeguards when a contract exists'], 1,
 'Section 12 lists multiple conditions. Finding one does not remove other applicable obligations and safeguards.', references=[NPC])
lesson('Rights and the people responsible for data', 'Distinguish a data subject, controller, processor, and data protection officer.', 's4', [9, 16],
 ['The **data subject** is the person the information relates to.', 'The **controller** determines processing; a **processor** handles data on its behalf.', 'Outsourcing does not erase the controller’s accountability.'],
 [('Roles follow what the parties do', 'A university may decide why student records are collected and how they are used. A service provider may process those records under its instructions. The labels in an agreement should reflect actual responsibilities; the same organization can have different roles for different activities.'),
  ('Make rights actionable', 'People need ways to obtain information about processing, access or correct records, and exercise other applicable rights. Those rights have legal conditions and exceptions. Security under Section 20 and accountability under Section 21 support handling the data responsibly even when a third party is involved.')],
 ('A university hires a platform to store enrollment records under its instructions.', 'The university is the controller for that activity; the platform acts as a processor. The student is the data subject. The university’s DPO helps oversee its privacy program rather than becoming the owner of the student’s information.'),
 ('What changes when processing is outsourced?', 'Another party carries out processing, so responsibilities, safeguards, and agreements must be managed. The controller does not simply hand away accountability.'),
 'Who determines the purposes and means of processing in the university example?', ['The student as a data subject', 'The storage hardware', 'The university as controller'], 2,
 'The controller decides the relevant purposes and means. The processor acts on its behalf for the described activity.',
 [table('Keep these roles separate', ['Role', 'Main idea'], [['Data subject', 'The individual the data relates to'], ['PIC / controller', 'Determines the processing'], ['PIP / processor', 'Processes on behalf of the controller'], ['DPO', 'Supports the organization’s privacy compliance'], ['NPC', 'Regulatory oversight and enforcement']])], references=[NPC])
lesson('The five pillars as an operating program', 'Connect privacy accountability activities to something an organization actually does.', 's4', [24, 37],
 ['Assign a **DPO**, assess privacy impact, and establish a privacy management program.', 'Implement actual privacy and security measures.', '**Rehearse response** and improve it; a document alone is not a program.'],
 [('A practical way to group the work', 'The deck groups accountability into five pillars: a responsible officer, impact assessment, a management program, protective measures, and breach-response exercises. Think of these as connected work. An assessment finds a risk; the program assigns ownership; a control treats it; an exercise tests whether the response works.'),
  ('Keep evidence and revisit decisions', 'An assessment is most useful before a new system or major change, while choices can still be adjusted. Record data flows, risks, safeguards, responsibilities, and unresolved issues. Review the program when processing changes instead of treating it as a one-time submission.')],
 ('A campus introduces facial recognition for attendance.', 'An impact assessment should examine necessity, alternatives, data flows, access, retention, and potential harm before deployment. The organization then decides on proportionate safeguards and responsibilities, rather than merely adding a privacy notice after launch.'),
 ('What makes a privacy impact assessment useful before launch?', 'It can change the design while there is still time to avoid or reduce risks, rather than only document problems after people are affected.'),
 'Which sequence best connects the five pillars?', ['Buy a tool and assume compliance is complete', 'Assess risks, assign actions, implement controls, and test response', 'Appoint a DPO and leave all other teams uninvolved'], 1,
 'The pillars support a continuing program. Ownership, assessment, implementation, and rehearsal need to work together.',
 [flow('From a new feature to accountable operation', ['Map the processing', 'Assess privacy risks', 'Assign decisions and responsibilities', 'Implement and verify safeguards', 'Exercise response and improve'])], references=[NPC])
lesson('Government data, violations, and local cases', 'Recognize why accountability includes access, disposal, and third-party handling.', 's4', [17, 41],
 ['Government-held sensitive information needs defined responsibility and authorized access.', 'Violations can concern **processing, access, disposal, concealment, or disclosure**.', 'Study local cases for the control and governance failure, not only the headline.'],
 [('Protection extends beyond the database', 'The deck covers sensitive information in government and accountability for contractors. Security includes who may access records, under what authority, how records are moved, and how they are disposed of. Printed copies and exports can create exposure outside the original application.'),
  ('Read cases critically', 'The module discusses Comeleak and passport-data concerns to connect public-sector systems with stewardship of personal data. A case should prompt questions about oversight, provider transitions, access controls, and response. Keep separate confirmed facts, allegations, and conclusions rather than infer liability from a headline.')],
 ('An agency replaces a contractor but does not confirm who retains copies of citizens’ records.', 'Plan data return or deletion, access revocation, records of handover, and continuing responsibilities. A contract ending does not by itself demonstrate secure disposal.'),
 ('Why can disposal be a privacy issue even without a network attack?', 'A discarded file, storage device, or retained contractor copy can expose personal data. Protection applies throughout the lifecycle, including its endpoint.'),
 'Which best addresses risk when changing data-processing providers?', ['Assume the old provider deletes everything automatically', 'Only change the logo in the user portal', 'Verify data handover, retention or deletion, and revoked access'], 2,
 'The transition should account for actual data copies and permissions. A new contract does not prove the old access and copies are gone.',
 correction='Slide 41 has a passport-data heading but describes the Bangladesh Bank / RCBC incident. Those are different cases. This lesson does not repeat the mismatched label or treat the slide’s penalty tables as a complete legal analysis.', references=[NPC])

module('Compliance frameworks and secure design', 'Give each standard a purpose, then apply risk management and threat modeling.')
lesson('Laws, standards, and frameworks', 'Explain what kind of requirement or guidance you are looking at.', 's5', [5, 30],
 ['A **law** creates legal obligations; a **standard** specifies requirements or practices in its scope.', 'A **framework** organizes outcomes, responsibilities, or controls.', 'A technical control can support several obligations; it does not prove complete compliance.'],
 [('Do not study the acronyms as synonyms', 'The module surveys a large ecosystem. Start by asking what problem each item helps solve. ISO/IEC 27001 concerns requirements for an information security management system. ISO/IEC 27002 gives guidance on information security controls. ISO/IEC 27003 concerns implementation guidance.'),
  ('Use the family as a map', 'The deck connects other standards with network security, application security, storage, cloud protection, and privacy. Knowing the category helps you select the right reference. The existence of a standard is not the same as a legal requirement for every organization to adopt it; applicability depends on laws, contracts, and context.')],
 ('A team needs a management system for security risks and also practical guidance on choosing access controls.', 'Think of ISO/IEC 27001 for ISMS requirements and ISO/IEC 27002 for control guidance. One is not simply a second name for the other.'),
 ('Why is a framework useful when laws already exist?', 'It helps translate broad obligations and objectives into organized risk decisions, responsibilities, controls, and review activities.'),
 'Which pairing best matches the module?', ['ISO 27001: ISMS requirements; ISO 27002: control guidance', 'ISO 27001: a Philippine criminal statute; ISO 27002: a court', 'Every ISO standard: automatic proof of legal compliance'], 0,
 'The standards have related but distinct roles. An ISMS manages risk systematically; control guidance supports the practical selection and use of safeguards.',
 [table('Navigate the standards named in the deck', ['Reference', 'Study association'], [['ISO/IEC 27001', 'ISMS requirements'], ['ISO/IEC 27002 / 27003', 'Controls guidance / implementation guidance'], ['ISO/IEC 27701 / 29100', 'Privacy information management / privacy framework'], ['ISO/IEC 27033 / 27034', 'Network security / application security'], ['ISO/IEC 27040', 'Storage security'], ['ISO/IEC 27017 / 27018', 'Cloud controls / personal data in public clouds']])])
lesson('NIST CSF and CMMC: outcomes and assurance', 'Choose a framework by the context rather than by its popularity.', 's5b', [4, 19],
 ['NIST CSF organizes cybersecurity risk outcomes.', '**CSF 2.0 has six functions**, including Govern.', 'CMMC concerns cybersecurity assurance for the US defense contracting context.'],
 [('Use functions to organize a program', 'Identify covers understanding assets and risk. Protect implements safeguards. Detect finds possible adverse events. Respond addresses detected incidents. Recover restores affected assets and operations. Govern connects strategy, policies, expectations, and oversight with the other functions.'),
  ('Match the framework to the need', 'NIST CSF helps organize desired outcomes and compare current and target states. CMMC assesses implementation of requirements in a particular contracting context. Neither label should be chosen only because a diagram looks comprehensive. Identify the organization’s obligations and desired assurance first.')],
 ('A school has backups but no assigned owner for cybersecurity risk decisions.', 'Backups support protection and recovery. Governance addresses who sets expectations, accepts risk, and checks whether the program meets organizational needs.'),
 ('What does Govern add to the familiar five CSF functions?', 'It makes cybersecurity strategy, policy, oversight, and organizational responsibility explicit across the risk management program.'),
 'Which function was added in NIST CSF 2.0?', ['Recover', 'Govern', 'Detect'], 1,
 'Govern is the additional function in CSF 2.0. The older five-function diagram is still present in your slides.',
 [flow('CSF 2.0 functions', ['Govern: establish direction and oversight', 'Identify: understand risk', 'Protect: implement safeguards', 'Detect: find adverse events', 'Respond: act on incidents', 'Recover: restore operations'])],
 correction='Your slides show the older five CSF functions and a five-level CMMC diagram. CSF 2.0 includes Govern; the current CMMC model uses three levels. Keep those versions separate when reviewing the deck.', references=[NIST, dict(title='Official reference: CMMC model overview', url='https://dodcio.defense.gov/Portals/0/Documents/CMMC/ModelOverview.pdf')])
lesson('Industry safeguards: payment cards and health data', 'Explain why applicability starts with the data and the organization’s role.', 's5c', [4, 11],
 ['**PCI DSS** addresses protection of payment card account data in its scope.', '**HIPAA Security Rule** concerns electronic protected health information for regulated entities.', 'Administrative, physical, and technical safeguards complement each other.'],
 [('Data type is a clue, not the entire analysis', 'A shop processing card payments needs to understand its payment-data environment. HIPAA is a US legal framework with defined covered entities and business associates; the presence of health information alone does not mean every organization worldwide is subject to it.'),
  ('Different safeguards solve different problems', 'Training and risk assessment are administrative measures. Protecting rooms and devices are physical measures. Authentication, access controls, encryption, and logging are technical measures. A complete approach considers the interaction among people, physical environments, and systems.')],
 ('A clinic encrypts records but leaves an unlocked, signed-in workstation in a public corridor.', 'Encryption alone does not solve unattended access. Session controls, workspace placement, staff practices, and physical safeguards also matter.'),
 ('Why should you check scope before applying a sector-specific standard?', 'The applicable duties depend on what data is involved, the organization’s role, contracts, and the legal framework, rather than a familiar acronym alone.'),
 'Which example is primarily a physical safeguard?', ['Locking a room containing record servers', 'Running a staff awareness session', 'Requiring a second authentication factor'], 0,
 'A locked server room restricts physical access. Training is administrative; authentication is technical.',
 [table('Recognize the category', ['Category', 'Example'], [['Administrative', 'Training, assigned responsibilities, risk assessment'], ['Physical', 'Controlled rooms, secured devices, protected work areas'], ['Technical', 'Access controls, encryption, logging']])])
lesson('Governance and a working compliance program', 'Connect COBIT, COSO, policies, inventories, and evidence.', 's5', [55, 86],
 ['**COBIT** connects enterprise IT governance and management with organizational goals.', '**COSO** addresses internal control and enterprise risk more broadly.', 'A program needs inventories, owners, controls, evidence, and review.'],
 [('Start from an objective', 'A compliance program is not just a folder of policies. Define what must be protected and which requirements apply. Inventory systems and data, identify risks, assign responsible people, implement controls, and collect evidence. Review whether the actions achieve the intended outcomes.'),
  ('Make the organizational connection', 'A governance framework helps leaders decide what direction to set and how to oversee results. Management turns direction into operating activities. An asset inventory makes these decisions concrete by recording systems, owners, configurations, and dependencies instead of relying on memory.')],
 ('An organization requires timely account removal but does not know which systems each employee can use.', 'The policy depends on a usable inventory and assigned owners. Link account records, offboarding responsibilities, and verification so the policy can be carried out and demonstrated.'),
 ('What connects a policy to evidence of compliance?', 'Named owners implement controls, record their operation, review outcomes, and correct gaps against the policy’s objectives.'),
 'Which is the most useful next step after writing a policy?', ['Store it and assume the problem is solved', 'Assign owners, implement controls, and verify evidence', 'Replace all risk decisions with a single checklist'], 1,
 'Policies express expectations. Operation and verification establish whether those expectations are met.',
 [flow('Operate the program', ['Identify obligations and assets', 'Assess gaps and risks', 'Assign owners and actions', 'Implement controls', 'Collect evidence and review', 'Correct gaps and repeat'])])
lesson('Secure development and threat modeling', 'Use four questions to bring security decisions into system design.', 's5d', [5, 19],
 ['The **Secure Development Lifecycle** integrates security throughout development.', 'Threat modeling starts with an understanding of the system and its data flows.', 'Ask: **what are we building, what can go wrong, what will we do, and did it work?**'],
 [('Make the system visible', 'Draw the people, processes, data stores, and flows involved in the feature. Mark trust boundaries where assumptions or privileges change. A data flow diagram helps show movement and interactions; an entity relationship diagram helps describe data relationships. They answer related but different questions.'),
  ('Treat the model as a living decision tool', 'Threat modeling is useful before implementation because a design can still change cheaply. It also matters during changes and operation. Prioritize threats by context, choose mitigations, and verify them with review and testing instead of ending the exercise at a list of possible attacks.')],
 ('A team designs online grade submission: teacher browser → API → grade database.', 'Ask who may submit grades, how authorization is checked at the API, what is stored, what crosses each boundary, and which records prove an approved change. The diagram points to questions that code and tests must answer.'),
 ('Why does threat modeling require a system model first?', 'You need to know the assets, interactions, data stores, and trust boundaries to identify plausible threats and meaningful mitigations.'),
 'Which activity best completes a threat-modeling decision?', ['List threats without owners', 'Choose controls without understanding the system', 'Verify whether the selected mitigations address the threats'], 2,
 'The fourth question asks whether the work was effective. A threat list without verification is incomplete.',
 [flow('The four-question loop', ['What are we working on?', 'What can go wrong?', 'What are we going to do about it?', 'Did we do a good job?'])])
lesson('STRIDE: classify the threat, choose a control', 'Distinguish the six STRIDE categories using a familiar application.', 's5d', [20, 26],
 ['STRIDE is a prompt for examining **six kinds of security threat**.', 'Classify the action and affected property, not merely the attacker.', 'A mitigation must address the specific threat and be verified.'],
 [('Look at what goes wrong', 'Spoofing concerns pretending to be another identity. Tampering changes data or behavior improperly. Repudiation concerns denying actions without adequate proof. Information disclosure exposes information. Denial of service disrupts availability. Elevation of privilege gives someone powers they should not have.'),
  ('One scenario can contain several threats', 'Stolen credentials may enable spoofing, followed by privilege escalation, record changes, and disclosure. STRIDE helps ensure the review considers different failure modes. Avoid assuming a single control covers all of them: authentication, authorization, audit evidence, and availability controls solve different parts of the problem.')],
 ('A student changes a request parameter and gains teacher-only grade-editing powers.', 'The unauthorized increase in capabilities is elevation of privilege. Server-side authorization must enforce permitted actions; hiding the edit button is not an adequate boundary.'),
 ('How do spoofing and elevation of privilege differ?', 'Spoofing pretends to be another identity. Elevation of privilege gains capabilities beyond those authorized, potentially even while using a legitimate identity.'),
 'An ordinary account gains administrator-only capabilities. Which STRIDE category is most direct?', ['Repudiation', 'Denial of service', 'Elevation of privilege'], 2,
 'The account gains unauthorized powers. The classification concerns privilege, whether or not another identity was impersonated.',
 [table('STRIDE in a student portal', ['Category', 'Example', 'Control idea'], [['Spoofing', 'Pretend to be a teacher', 'Strong authentication'], ['Tampering', 'Alter submitted grades', 'Authorization and integrity checks'], ['Repudiation', 'Deny making a grade change', 'Protected audit evidence'], ['Information disclosure', 'Read another student’s record', 'Access restrictions'], ['Denial of service', 'Make enrollment unavailable', 'Capacity and abuse controls'], ['Elevation of privilege', 'Gain administrator actions', 'Server-side role enforcement']])])

module('International law and coordinated response', 'Handle overlapping jurisdictions, global standards, and evidence across organizations.')
lesson('One service, several jurisdictions', 'Explain why a global service needs a map of applicable obligations.', 's6a', [5, 24],
 ['A single service may involve users, establishments, and providers in several places.', 'Do not assume one law cancels another.', 'Map processing and applicable rules before selecting a transfer mechanism.'],
 [('Follow the processing, not the brand name', 'A company may operate in one country while collecting information through another establishment and relying on providers elsewhere. Determine the actors, purposes, data categories, and locations, then assess the reach of each relevant framework. A provider’s reputation does not establish your own compliance.'),
  ('Turn overlap into an operational map', 'The module revisits GDPR principles, rights, and compliance roadmaps in a global setting. Link an obligation to an activity: access requests need a response process; retention needs deletion practices; transfer restrictions need an assessed transfer route. Record why each rule applies and who is responsible.')],
 ('A Philippine service markets subscriptions to people in the EU and uses an overseas analytics provider.', 'Examine GDPR scope using the actual offering or monitoring activities, Philippine obligations relevant to the organization, and the analytics data flows. Do not decide from citizenship or hosting location alone.'),
 ('What information belongs in an international compliance map?', 'Actors and roles, data categories, purposes, relevant establishments and activities, recipients, locations, applicable rules, and responsible owners.'),
 'What is the strongest starting point for a multinational privacy assessment?', ['Use whichever country has the shortest law', 'Map processing activities and assess each relevant law’s scope', 'Assume the hosting provider handles all legal duties'], 1,
 'Mapping the processing makes applicability and responsibility assessable. Geography alone or a provider promise is insufficient.',
 correction='The decks sometimes equate lawful processing with consent. GDPR Article 6 provides several lawful bases. Treat consent as one basis and assess the correct conditions for each processing activity.', references=[GDPR])
lesson('International organizations and different kinds of rules', 'Distinguish cooperation, standards, and enforceable legal requirements.', 's6a', [25, 32],
 ['**OECD, APEC, and ISO** play different roles in international cooperation and standards.', 'A convention, national law, standard, and policy resolution do not have identical legal effects.', 'Cross-border cooperation helps where data and incidents span jurisdictions.'],
 [('Classify the instrument', 'The international survey includes privacy regulations, national laws, cooperative arrangements, and standards. Ask who issued the instrument, who it addresses, and how it becomes applicable. A treaty depends on its terms and state participation; a standard is not automatically a criminal statute.'),
  ('Why cooperation matters', 'Investigations and data handling may cross national boundaries. Organizations and authorities need ways to coordinate while respecting applicable powers and safeguards. Harmonization can reduce friction, but it does not make all national requirements identical or remove local accountability.')],
 ('A supplier says it follows an international standard, while a customer asks which transfer rules govern their records.', 'The standard may support safeguards. It does not by itself answer territorial scope, the lawful transfer route, or the parties’ respective duties.'),
 ('What should you ask before treating an international instrument as binding?', 'Identify its issuer, legal nature, scope, participation or adoption requirements, and the way it applies to the actors and activity involved.'),
 'Which statement is most accurate?', ['Every international guideline creates the same criminal penalties', 'Following one standard displaces all national laws', 'Different instruments have different scope and legal effects'], 2,
 'The legal nature and applicability of an instrument must be checked. Standards, laws, conventions, and resolutions should not be treated as interchangeable.')
lesson('Coordinated response and preserving evidence', 'Connect technical response decisions with a reliable account of what happened.', 's6b', [6, 14],
 ['Coordinate technical responders with management, privacy, and legal responsibilities.', '**Preserve evidence** and document relevant actions.', 'Validate recovery and review the incident before closure.'],
 [('A response needs both action and a record', 'The subtopic breaks incident response into awareness, assessment, escalation, investigation, containment, eradication, recovery, and closure activities. These are more detailed steps within the lifecycle studied earlier. Teams may revisit decisions as the scope changes.'),
  ('Protect the reliability of the record', 'Logs, system images, and other records can explain the incident and support later review. Record collection and handling, timestamps, decision makers, and changes made during response. Avoid unnecessary alteration, and coordinate urgent protective action with appropriate evidence preservation.')],
 ('An administrator wants to wipe a compromised server immediately, while responders still need to establish what records were accessed.', 'Contain the threat and coordinate evidence preservation before unnecessary destructive changes. Recovery speed and reliable investigation both matter; the response plan should help the team manage that tradeoff.'),
 ('Why document response actions as well as attacker activity?', 'Your own actions can change systems and evidence. Recording them helps others interpret the timeline, validate findings, and assess the response.'),
 'Which practice best supports a reliable investigation?', ['Change systems without recording anything', 'Document collection, handling, timestamps, and response changes', 'Treat the first alert as the complete incident timeline'], 1,
 'A traceable record makes evidence and decisions easier to interpret. Alerts are a starting point for investigation, not a complete account.')
lesson('SIEM, privacy risk, and compliance evidence', 'Explain what a SIEM contributes and what still requires human assessment.', 's6b', [15, 31],
 ['A **SIEM** collects, normalizes, correlates, and analyzes security event data.', 'Alerts and logs can support detection, investigation, and accountability.', '**A dashboard is not a legal determination** and logs themselves need protection.'],
 [('From scattered records to a timeline', 'An identity provider records sign-ins, a firewall records connections, and an application records data access. Correlation can connect unusual logins with an unexpected export. The SIEM helps responders find patterns across records that would be harder to interpret separately.'),
  ('Use the evidence responsibly', 'Someone must assess whether an alert is an incident, what data was affected, and which obligations apply. Logging also processes information: restrict access, choose relevant events, and manage retention. The deck’s discussion of privacy risk reminds you to consider effects on people as well as attacks on systems.')],
 ('A SIEM flags a large export after repeated failed logins.', 'Investigate the user, authorization, records involved, and timeline. The alert supports scoping; it does not automatically establish that a reportable breach occurred or identify every affected person.'),
 ('Why does buying a SIEM not finish a compliance program?', 'The organization still needs correct configuration, relevant data, monitoring responsibilities, investigation, legal assessment, response, and protection of the logs.'),
 'What is the most accurate description of a SIEM alert?', ['An automatically final legal finding', 'Proof that all data is safe', 'A signal requiring contextual assessment'], 2,
 'Correlation helps identify suspicious activity. People and processes must determine its meaning and appropriate response.',
 correction='The decks show a five-function NIST cybersecurity diagram near discussion of the Privacy Framework. Do not treat the two frameworks as identical. CSF 2.0 has six functions, including Govern.', references=[NIST])

module('Emerging technologies: legal and ethical choices', 'Apply familiar privacy and security questions to AI, blockchain, IoT, and cloud services.')
lesson('AI: privacy, fairness, and accountability', 'Explain why an accurate-looking prediction may still be unfair or difficult to justify.', 's7', [5, 10],
 ['AI concerns include **personal data use, bias, transparency, and accountability**.', 'Training data and evaluation choices influence outcomes.', 'Identify who can explain, challenge, and correct a harmful decision.'],
 [('Follow the decision, not just the model', 'An AI system takes data and produces an output used in a real process. Examine what data was collected, whether it represents the affected people, how the output is interpreted, and what happens when it is wrong. Accuracy measured across everyone can conceal different error rates across groups.'),
  ('Accountability needs an owner', 'Transparency means providing an appropriate explanation of relevant processing and decisions. Accountability asks who is responsible for evaluating the system and handling problems. The fact that software generated an output does not resolve an organization’s responsibilities to the people affected.')],
 ('An automated scholarship ranking performs well overall but repeatedly underrates applicants from a group poorly represented in its training data.', 'Assess the data, outcomes for different groups, decision process, and a route to human review. A high average score alone does not establish fair treatment.'),
 ('What should you ask besides “how accurate is this AI?”', 'Ask whose data is used, whose errors are hidden by averages, how outputs affect people, and who can explain and review a decision.'),
 'Which best addresses the possibility that overall accuracy hides unfair outcomes?', ['Evaluate errors across relevant groups and review the decision process', 'Use only the overall average', 'Remove all routes for questioning decisions'], 0,
 'Group-level evaluation and process review can reveal harms hidden by an aggregate metric.',
 correction='Your deck describes the EU AI Regulation as proposed. The AI Act entered into force on 1 August 2024. Its obligations have phased application; consult the official timeline rather than reuse the deck’s proposal status.', references=[dict(title='Official reference: AI Act entered into force', url='https://commission.europa.eu/news-and-media/news/ai-act-enters-force-2024-08-01_en')])
lesson('Blockchain: immutability meets personal data', 'Explain the tension between persistent records and correction or erasure.', 's7', [12, 16],
 ['Blockchain’s resistance to alteration can conflict with changing or deleting personal information.', '**Off-chain storage** can reduce direct exposure of personal data on-chain.', 'Decentralization does not automatically resolve responsibility or privacy.'],
 [('A useful property can create a new problem', 'A durable shared ledger can help establish a history of transactions. The same persistence becomes difficult when personal information is inaccurate, excessive, or subject to a valid deletion request. Consider what genuinely needs to be placed on the ledger before choosing the technology.'),
  ('Reduce the data exposed by the design', 'The module discusses keeping personal data off-chain with a reference or hash on-chain. This changes the design problem, but does not automatically solve every privacy issue. References, linkability, copies, and the parties controlling the off-chain data still need examination.')],
 ('A team proposes putting complete student medical records on a shared immutable ledger.', 'Ask whether the ledger needs the underlying sensitive details at all. A design using controlled off-chain records may reduce exposure, while references and access arrangements still require assessment.'),
 ('Why is immutability not always a benefit for personal data?', 'It makes later correction or deletion difficult, and may preserve information longer or more widely than is appropriate.'),
 'Which design question should come first?', ['How can we place the most personal data on-chain?', 'Does this information need to be on the ledger at all?', 'Can decentralization replace all accountability?'], 1,
 'Necessity should guide the architecture. Reducing direct personal data on a persistent ledger can avoid creating a difficult privacy problem.')
lesson('IoT: sensors, surveillance, and secure defaults', 'Identify the privacy and security consequences of a connected device.', 's7', [17, 21],
 ['IoT devices collect and exchange data, often continuously.', 'Weak defaults and missing updates can expose both data and device control.', 'Consider people nearby who did not actively choose the device.'],
 [('Collection can be easy to overlook', 'A camera, wearable, or smart speaker may collect information passively. Determine what it senses, when it operates, where data goes, who can access it, and how long it remains. A device owner is not necessarily the only person affected.'),
  ('Security is part of the product lifecycle', 'Default credentials, exposed interfaces, missing updates, and insecure communication can create entry points. Secure design includes appropriate defaults and a realistic maintenance plan. Privacy design also considers unnecessary sensing, visibility of operation, and meaningful information for affected people.')],
 ('A classroom installs a connected camera that sends footage to a provider’s cloud.', 'Assess the purpose, field of view, recording schedule, notices, access, retention, transfer arrangements, credentials, and update support. Changing the password addresses one risk, not the whole system.'),
 ('Why is “the owner agreed” insufficient when assessing a classroom camera?', 'Students, staff, and visitors may be recorded too. The assessment must consider the people affected and the applicable processing conditions and safeguards.'),
 'Which assessment covers both privacy and security?', ['Check only whether the camera powers on', 'Change the password and ignore data flows', 'Review necessary sensing, access, retention, and update support'], 2,
 'A connected sensor is both a data collection system and a maintained computing device. Both aspects need attention.')
lesson('Cloud and big data: shared responsibility', 'Explain what remains the customer’s responsibility when using a cloud service.', 's7', [22, 26],
 ['A cloud provider and customer have different responsibilities depending on the service.', 'Access settings, data selection, and retention remain important customer decisions.', 'Big datasets can increase the consequences of exposure and linkability.'],
 [('Outsourcing infrastructure does not outsource every decision', 'A provider may operate physical infrastructure and parts of the platform while the customer controls users, application behavior, and which data is stored. The exact split depends on the service and agreement. Understand the split instead of assuming the provider handles everything.'),
  ('Data flows still matter', 'Cloud services may replicate information and involve subprocessors in other jurisdictions. Big-data analysis can also reveal patterns or allow records to be linked in new ways. Apply minimization, access restrictions, retention decisions, and appropriate transfer assessment to the actual processing.')],
 ('A company uses a reputable cloud platform but makes its customer file bucket publicly accessible.', 'The provider’s infrastructure security does not automatically correct the customer’s sharing configuration. Verify access settings and monitor exposure in the customer’s part of the service.'),
 ('What should a cloud responsibility review clarify?', 'Which party handles each security and privacy task, what the customer must configure, where data flows, and how access, response, and deletion work.'),
 'Which is the most accurate conclusion about cloud security?', ['Responsibilities must be understood for the actual service', 'The provider always configures every customer permission', 'A trusted brand eliminates all transfer questions'], 0,
 'Responsibility depends on the service and agreement. Customers still need to understand their data and configuration decisions.')

module('Cybersecurity in the Philippine context', 'Connect local threats, public policy, cybercrime, and the human effects of incidents.')
lesson('Local threats need layers of protection', 'Connect awareness, infrastructure, skills, and critical services.', 's8', [5, 11],
 ['Awareness gaps, infrastructure weaknesses, and skills shortages can interact.', 'Critical services require attention to continuity as well as confidentiality.', 'National strategy coordinates responsibilities; organizations still need operational controls.'],
 [('Look beyond an individual mistake', 'The module describes social engineering alongside organizational and infrastructure challenges. A phishing incident may begin with a deceptive message, but its impact depends on authentication, access scope, monitoring, reporting channels, and recovery. Improving only one person’s vigilance leaves other layers unexamined.'),
  ('Connect national goals to local actions', 'Public strategy can guide coordination and priorities. An organization translates those priorities into known assets, assigned owners, tested response, staff training, and protection for essential services. An inventory and a working escalation path often matter more than a policy title on its own.')],
 ('A municipal office trains staff about phishing but has shared administrator accounts and no tested backups.', 'Training addresses one entry point. Individual accounts, appropriate access, stronger authentication, monitoring, and tested recovery address additional consequences and failure points.'),
 ('Why is awareness training valuable but incomplete?', 'People can still make mistakes, and attacks can exploit technical weaknesses. Layered safeguards reduce both the chance and impact of compromise.'),
 'Which plan best reflects layered protection?', ['Combine training, limited access, monitoring, and tested recovery', 'Rely only on employees recognizing every scam', 'Buy one tool without assigning any operating responsibilities'], 0,
 'Complementary layers account for different failure modes and help reduce damage when one measure fails.',
 correction='The slides refer to a National Cybersecurity Plan 2022. Executive Order 58 adopted the National Cybersecurity Plan 2023–2028 in April 2024; use the newer plan when discussing current policy.', references=[dict(title='Official reference: Executive Order 58, National Cybersecurity Plan 2023–2028', url='https://elibrary.judiciary.gov.ph/thebookshelf/showdocs/5/97132')])
lesson('RA 10175: classify the conduct carefully', 'Distinguish cybercrime categories from privacy and compliance questions.', 's8', [12, 17],
 ['RA 10175 is the **Cybercrime Prevention Act of 2012**.', 'The deck discusses illegal access, interference, and computer-related offenses.', 'Identify conduct and applicable provisions; do not infer a legal conclusion from a label alone.'],
 [('Describe the act before naming the offense', 'Unauthorized entry into a system differs from altering data, interrupting a service, or using a computer to commit fraud. Start with what happened, the authorization involved, the evidence, and the effect. The same incident may raise privacy, cybersecurity, and other legal issues.'),
  ('Read tables with care', 'A slide’s short penalty table cannot express every statutory element, amendment, or court ruling. Use it as a map to the relevant primary source. For study, focus first on the distinguishing conduct and then check the legal wording instead of treating every example as an automatic finding of guilt.')],
 ('A person enters a private account without authorization and then alters its records.', 'Unauthorized access and alteration are different actions to analyze. Preserve the facts and evidence before deciding which provisions and elements are relevant.'),
 ('Why should a cybercrime analysis start with conduct and authorization?', 'Those facts help identify potentially relevant provisions and distinguish access, interference, deception, and disclosure, rather than jump from a headline to liability.'),
 'Which is the best starting point for classifying a suspected cyber offense?', ['Assume all online misconduct is one offense', 'Identify the conduct, authorization, evidence, and relevant provision', 'Choose the highest penalty visible on a slide'], 1,
 'Legal classification depends on the elements and facts. A short label or penalty table is not enough.',
 correction='The deck lists unsolicited commercial communications as a punishable RA 10175 offense. The Supreme Court’s Disini ruling declared Section 4(c)(3) unconstitutional. This lesson does not present that provision as enforceable.', references=[dict(title='Official reference: Supreme Court, Disini v. Secretary of Justice', url='https://elibrary.judiciary.gov.ph/assets/pdf/philrep/2014/G.R.%20No.%20203335.pdf')])
lesson('Use local cases to improve a system', 'Turn a case discussion into actions for prevention, detection, and recovery.', 's8', [18, 20],
 ['Separate **defacement, service disruption, and personal data exposure**.', 'The harm depends on which assets and people were affected.', 'Turn each case into questions about controls, evidence, and response.'],
 [('The headline does not define the whole incident', 'A changed webpage may indicate unauthorized modification, while a stolen dataset concerns confidentiality. Both may happen together, but one does not prove the other. The deck’s examples prompt a closer look at scope, affected services, personal data, and what the investigation establishes.'),
  ('Create actions from the analysis', 'Ask how access was obtained, how the activity was detected, which safeguards limited damage, and how operations were restored. Assign improvements to owners. Treat uncertain or disputed case details as matters to verify rather than repeat them as established facts.')],
 ('An office discovers a defaced homepage and immediately announces that all citizen records were stolen.', 'Investigate scope before making that claim. Defacement demonstrates an integrity problem on the affected page; record theft requires additional evidence. Communicate known facts and uncertainty clearly.'),
 ('What can and cannot be concluded from a defaced webpage alone?', 'It indicates unauthorized modification of the page. It does not, on its own, prove all backend data was accessed or that no other system was affected.'),
 'What does a defaced homepage establish most directly?', ['Unauthorized change to the affected page', 'Proof that every database was stolen', 'Proof that no personal data could have been affected'], 0,
 'The observed change concerns integrity. Investigate other systems and data before reaching conclusions about confidentiality or total scope.')
lesson('Human impact, ethics, and a final study method', 'Analyze cybercrime without losing sight of victims, rights, and responsible response.', 's8', [21, 27],
 ['Cybercrime can cause financial, psychological, family, and community harm.', 'Victim protection and responsible reporting matter alongside investigation.', 'Avoid online vigilantism and unnecessary exposure of personal information.'],
 [('People experience the consequences', 'The module discusses exploitation, cyber-enabled trafficking, manipulation, and effects on trust and family life. Study these as harms requiring prevention, support, and responsible institutional action. Avoid treating victims’ experiences as sensational examples or assuming a single technical control solves a social problem.'),
  ('Connect the whole course', 'A useful analysis names the affected people and assets, the threat and vulnerability, the applicable rights or obligations, safeguards, and response. Explain uncertainty and preserve evidence responsibly. This combines the technical and legal vocabulary with a practical view of consequences.' )],
 ('A group wants to expose a suspected scammer by publishing private addresses and family details.', 'Publicly spreading personal information can create further harm and misidentify people. Use appropriate reporting channels and preserve relevant evidence without unnecessarily distributing private details.'),
 ('Analyze a new incident using the course’s core questions.', 'Who and what are affected? What happened and what is known? Which weakness and threat are involved? What rights and obligations may apply? Which controls and response actions reduce harm? What evidence supports the conclusion?'),
 'Which response best supports victims and responsible investigation?', ['Publish relatives’ private details to pressure a suspect', 'Treat allegations as final findings', 'Preserve relevant evidence and use appropriate reporting channels'], 2,
 'Responsible handling supports investigation while reducing additional exposure and harm. Avoid spreading unverified accusations or unnecessary personal information.',
 [flow('A reusable case-analysis checklist', ['People and assets: who or what matters?', 'Facts and uncertainty: what do we know?', 'Threat and weakness: what went wrong?', 'Rights and rules: what obligations are relevant?', 'Controls and response: how can harm be reduced?', 'Evidence and review: can we justify the conclusion?'])])

def build(archive):
    DEST.mkdir(parents=True, exist_ok=True)
    patterns = [
        ('s1', r'Module 1 -', 'Module 1: Foundations'), ('s2', r'Module 2 -', 'Module 2: Data protection'),
        ('s3', r'Module 3 -', 'Module 3: Incident response'), ('s4', r'Module 4 -', 'Module 4: Philippine privacy law'),
        ('s5', r'Module 5 -', 'Module 5: Compliance and standards'), ('s5b', r'Module 5 Subtopic 2', 'Module 5, subtopic 2: National frameworks'),
        ('s5c', r'Module 5 Subtopic 3', 'Module 5, subtopic 3: Industry and governance'), ('s5d', r'Module 5  Subtopic 5', 'Module 5, subtopic 5: Secure development and STRIDE'),
        ('s6', r'Module 6 -', 'Module 6: International legal aspects'), ('s6a', r'Module 6 Subtopic 1', 'Module 6, subtopic 1: Global data protection'),
        ('s6b', r'Module 6 Subtopic 2', 'Module 6, subtopic 2: Coordinated incident response'),
        ('s7', r'Module 7 -', 'Module 7: Emerging technologies'), ('s8', r'Module 8 -', 'Module 8: Philippine context')]
    with zipfile.ZipFile(archive) as z:
        names = [n for n in z.namelist() if '/Module Powerpoint 1-8/' in n and n.lower().endswith('.pdf')]
        for sid, pattern, title in patterns:
            name = next(n for n in names if Path(n).name.startswith(pattern))
            target = DEST / 'sources' / f'{sid}.pdf'
            target.parent.mkdir(exist_ok=True)
            target.write_bytes(z.read(name))
            SOURCES.append(dict(id=sid, title=title, originalName=Path(name).name, url=f'/courses/it0204/sources/{sid}.pdf'))
    course = dict(id='it0204', code='IT0204', title='Cybersecurity and Privacy Laws',
        description='Understand the laws, reason through real situations, and connect privacy with secure systems.',
        editorialNote='Prepared from Modules 1–8 and their subtopic decks. Lessons explain the central concepts in plain language and add labeled teaching examples. They are a guided study companion, not a slide-by-slide transcript. Source clarifications identify selected outdated or simplified claims; original slides remain available for detailed reference.',
        version=1, sources=SOURCES, modules=MODULES)
    count = sum(len(m['lessons']) for m in MODULES)
    (DEST / 'course.json').write_text(json.dumps(course, ensure_ascii=False, indent=2), encoding='utf-8')
    entry = {k: course[k] for k in ['id', 'code', 'title', 'description']}
    entry.update(moduleCount=len(MODULES), lessonCount=count, content='/courses/it0204/course.json')
    catalog_path = DEST.parent / 'catalog.json'
    catalog = json.loads(catalog_path.read_text(encoding='utf-8')) if catalog_path.exists() else []
    catalog = [v for v in catalog if v['id'] != course['id']] + [entry]
    catalog_path.write_text(json.dumps(catalog, indent=2), encoding='utf-8')
    print(f'Built {len(MODULES)} modules, {count} lessons, {len(SOURCES)} source decks.')

if __name__ == '__main__':
    build(sys.argv[1])
